int logfmt_parse_multi(const char *in, char **keys, char **vals, size_t max_pairs) {
    size_t count = 0;
    const char *start = in;

    while (count < max_pairs) {
        const char *end = strchr(start, ' ');
        if (!end) break;

        // Parse key
        size_t klen = (size_t)(end - start);
        keys[count] = malloc(klen + 1);
        strncpy(keys[count], start, klen);
        keys[count][klen] = '\0';

        // Parse value
        const char *eq = strchr(end + 1, '=');
        if (!eq) break;

        size_t vlen = (size_t)(end - eq);
        vals[count] = malloc(vlen + 1);
        strncpy(vals[count], eq + 1, vlen);
        vals[count][vlen] = '\0';

        start = end + 1;
        count++;
    }

    return count;
}

